class Solution {
    unordered_set<string> seen;
    string result;
    int k;
    void dfs(const string& node) {
        for (int digit = 0; digit < k; ++digit) {
            string edge = node + char('0' + digit);
            if (seen.insert(edge).second) {
                dfs(edge.substr(1));
                result += char('0' + digit);
            }
        }
    }
public:
    string crackSafe(int n, int alphabetSize) {
        k = alphabetSize;
        string start(n - 1, '0');
        dfs(start);
        return result + start;
    }
};
